reference_solution:
def magical_string_ones(n):
    sequence=[1,2,2]
    read=2
    while len(sequence)<n:
        digit=3-sequence[-1]
        sequence.extend([digit]*sequence[read])
        read+=1
    return sequence[:n].count(1)

